type pageContext struct { id *uuid.UUID; name, slot string }

func requiredFieldsMissingRouting(siteID uuid.UUID, page pageContext, scopeKey string) (itemKey, handler, status string) {
	if page.id != nil && page.slot != "" {
		return fmt.Sprintf("required_fields_missing:%s:%s", *page.id, page.slot), "required-fields-missing-handler", "detected"
	}
	return fmt.Sprintf("required_fields_missing:%s:%s", siteID, scopeKey), "", "needs_human_review"
}
// in the emitter: spec["page_name"], spec["slot_name"]; workItem{ pageID: page.id, itemKey: itemKey, handlerAgent: handler, status: status }

func editPageContext(page *PageInfo, pcData map[string]interface{}) pageContext {
	if page == nil { return pageContext{} }
	pc := pageContext{name: page.Name, slot: getStringVal(pcData, "slot_name")}
	if page.ID != uuid.Nil { id := page.ID; pc.id = &id }
	return pc
}
